DECLARE
  TYPE row_map IS TABLE OF VARCHAR2(32767) INDEX BY VARCHAR2(128);
  actual row_map;
  oversized NUMBER;
BEGIN
  FOR r IN (SELECT TO_CHAR(ID) AS ROW_ID, CASE WHEN ID IS NULL THEN 'N;' ELSE 'V'||LENGTH(ID)||':'||ID||';' END || CASE WHEN LOCALENAME IS NULL THEN 'N;' ELSE 'V'||LENGTH(LOCALENAME)||':'||LOCALENAME||';' END AS SIGNATURE FROM T_CORE_I18N_CONFIG) LOOP
    actual(r.ROW_ID) := r.SIGNATURE;
  END LOOP;
  IF actual.COUNT <> 2 THEN RAISE_APPLICATION_ERROR(-20121, 'Technical bootstrap row count differs: T_CORE_I18N_CONFIG'); END IF;
  IF NOT actual.EXISTS('en-US') THEN RAISE_APPLICATION_ERROR(-20122, 'Missing technical bootstrap row: T_CORE_I18N_CONFIG'); END IF;
  IF actual('en-US') <> 'V5:en-US;V6:英语(美国);' THEN RAISE_APPLICATION_ERROR(-20122, 'Technical bootstrap row differs: T_CORE_I18N_CONFIG'); END IF;
  IF NOT actual.EXISTS('zh-CN') THEN RAISE_APPLICATION_ERROR(-20122, 'Missing technical bootstrap row: T_CORE_I18N_CONFIG'); END IF;
  IF actual('zh-CN') <> 'V5:zh-CN;V4:简体中文;' THEN RAISE_APPLICATION_ERROR(-20122, 'Technical bootstrap row differs: T_CORE_I18N_CONFIG'); END IF;
END;
