  actual row_map;
  oversized NUMBER;
BEGIN
  SELECT COUNT(*) INTO oversized FROM T_CORE_I18N_MESSAGE WHERE DBMS_LOB.GETLENGTH(MESSAGE)>1000;
  IF oversized <> 0 THEN RAISE_APPLICATION_ERROR(-20123, 'Technical bootstrap text exceeds reviewed capacity.'); END IF;
  FOR r IN (SELECT TO_CHAR(ID) AS ROW_ID, CASE WHEN ID IS NULL THEN 'N;' ELSE 'V'||LENGTH(TO_CHAR(ID,'TM9','NLS_NUMERIC_CHARACTERS=''.,'''))||':'||TO_CHAR(ID,'TM9','NLS_NUMERIC_CHARACTERS=''.,''')||';' END || CASE WHEN I18NID IS NULL THEN 'N;' ELSE 'V'||LENGTH(TO_CHAR(I18NID,'TM9','NLS_NUMERIC_CHARACTERS=''.,'''))||':'||TO_CHAR(I18NID,'TM9','NLS_NUMERIC_CHARACTERS=''.,''')||';' END || CASE WHEN I18NCONFIGID IS NULL THEN 'N;' ELSE 'V'||LENGTH(I18NCONFIGID)||':'||I18NCONFIGID||';' END || CASE WHEN MESSAGE IS NULL THEN 'N;' ELSE 'V'||DBMS_LOB.GETLENGTH(MESSAGE)||':'||DBMS_LOB.SUBSTR(MESSAGE,1000,1)||';' END AS SIGNATURE FROM T_CORE_I18N_MESSAGE) LOOP
    actual(r.ROW_ID) := r.SIGNATURE;
  END LOOP;
