DECLARE
  TYPE row_map IS TABLE OF VARCHAR2(32767) INDEX BY VARCHAR2(128);
  actual row_map;
  oversized NUMBER;
BEGIN
  FOR r IN (SELECT TO_CHAR(ID) AS ROW_ID, CASE WHEN ID IS NULL THEN 'N;' ELSE 'V'||LENGTH(ID)||':'||ID||';' END || CASE WHEN MENUNAME IS NULL THEN 'N;' ELSE 'V'||LENGTH(MENUNAME)||':'||MENUNAME||';' END || CASE WHEN PARENTID IS NULL THEN 'N;' ELSE 'V'||LENGTH(PARENTID)||':'||PARENTID||';' END || CASE WHEN ORDERNO IS NULL THEN 'N;' ELSE 'V'||LENGTH(TO_CHAR(ORDERNO,'TM9','NLS_NUMERIC_CHARACTERS=''.,'''))||':'||TO_CHAR(ORDERNO,'TM9','NLS_NUMERIC_CHARACTERS=''.,''')||';' END || CASE WHEN MENUINITNAME IS NULL THEN 'N;' ELSE 'V'||LENGTH(MENUINITNAME)||':'||MENUINITNAME||';' END || CASE WHEN ICON IS NULL THEN 'N;' ELSE 'V'||LENGTH(ICON)||':'||ICON||';' END || CASE WHEN TODOICON IS NULL THEN 'N;' ELSE 'V'||LENGTH(TODOICON)||':'||TODOICON||';' END || CASE WHEN I18NCODE IS NULL THEN 'N;' ELSE 'V'||LENGTH(I18NCODE)||':'||I18NCODE||';' END || CASE WHEN HREF IS NULL THEN 'N;' ELSE 'V'||LENGTH(HREF)||':'||HREF||';' END AS SIGNATURE FROM T_CORE_MENU) LOOP
    actual(r.ROW_ID) := r.SIGNATURE;
  END LOOP;
  IF actual.COUNT <> 392 THEN RAISE_APPLICATION_ERROR(-20121, 'Technical bootstrap row count differs: T_CORE_MENU'); END IF;
  IF NOT actual.EXISTS('10') THEN RAISE_APPLICATION_ERROR(-20122, 'Missing technical bootstrap row: T_CORE_MENU'); END IF;
  IF actual('10') <> 'V2:10;V6:全面资源管理;N;V2:10;V6:全面资源管理;V7:004.svg;V7:025.png;N;N;' THEN RAISE_APPLICATION_ERROR(-20122, 'Technical bootstrap row differs: T_CORE_MENU'); END IF;
  IF NOT actual.EXISTS('1000') THEN RAISE_APPLICATION_ERROR(-20122, 'Missing technical bootstrap row: T_CORE_MENU'); END IF;
  IF actual('1000') <> 'V4:1000;V4:人员管理;V2:10;V4:1008;V4:人员管理;V7:048.svg;N;N;N;' THEN RAISE_APPLICATION_ERROR(-20122, 'Technical bootstrap row differs: T_CORE_MENU'); END IF;
  IF NOT actual.EXISTS('100001') THEN RAISE_APPLICATION_ERROR(-20122, 'Missing technical bootstrap row: T_CORE_MENU'); END IF;
