  FOR r IN (SELECT TO_CHAR(ID) AS ROW_ID, CASE WHEN ID IS NULL THEN 'N;' ELSE 'V'||LENGTH(TO_CHAR(ID,'TM9','NLS_NUMERIC_CHARACTERS=''.,'''))||':'||TO_CHAR(ID,'TM9','NLS_NUMERIC_CHARACTERS=''.,''')||';' END || CASE WHEN CODE IS NULL THEN 'N;' ELSE 'V'||LENGTH(CODE)||':'||CODE||';' END || CASE WHEN CODENAME IS NULL THEN 'N;' ELSE 'V'||DBMS_LOB.GETLENGTH(CODENAME)||':'||DBMS_LOB.SUBSTR(CODENAME,1000,1)||';' END || CASE WHEN CODECATEGORYID IS NULL THEN 'N;' ELSE 'V'||LENGTH(CODECATEGORYID)||':'||CODECATEGORYID||';' END || CASE WHEN ORDERNO IS NULL THEN 'N;' ELSE 'V'||LENGTH(TO_CHAR(ORDERNO,'TM9','NLS_NUMERIC_CHARACTERS=''.,'''))||':'||TO_CHAR(ORDERNO,'TM9','NLS_NUMERIC_CHARACTERS=''.,''')||';' END || CASE WHEN LASTSUSPENDEDFLAG IS NULL THEN 'N;' ELSE 'V'||LENGTH(LASTSUSPENDEDFLAG)||':'||LASTSUSPENDEDFLAG||';' END || CASE WHEN I18NCODE IS NULL THEN 'N;' ELSE 'V'||LENGTH(I18NCODE)||':'||I18NCODE||';' END AS SIGNATURE FROM T_CORE_CODE) LOOP
